(function(){let e=document.createElement(`link`).relList;if(e&&e.supports&&e.supports(`modulepreload`))return;for(let e of document.querySelectorAll(`link[rel="modulepreload"]`))n(e);new MutationObserver(e=>{for(let t of e)if(t.type===`childList`)for(let e of t.addedNodes)e.tagName===`LINK`&&e.rel===`modulepreload`&&n(e)}).observe(document,{childList:!0,subtree:!0});function t(e){let t={};return e.integrity&&(t.integrity=e.integrity),e.referrerPolicy&&(t.referrerPolicy=e.referrerPolicy),t.credentials=e.crossOrigin===`use-credentials`?`include`:e.crossOrigin===`anonymous`?`omit`:`same-origin`,t}function n(e){if(e.ep)return;e.ep=!0;let n=t(e);fetch(e.href,n)}})();var e={hauteur_visage:189.1,tiers_haut:67.8,tiers_milieu:59,tiers_bas:62.3,largeur_pommettes:151,largeur_machoire:112.2,largeur_front:116.6,largeur_nez:36.7,largeur_bouche:47,intercanthale:29.6,fente_palpebrale:30.2,longueur_nez:59,sn_st:21.4,st_gn:40.9,oeil_sourcil:11.9,projection_nez:11.3,ratios:{hauteur_sur_largeur:1.25,machoire_sur_pommettes:.74,front_sur_pommettes:.77,nez_sur_intercanthale:1.24,bouche_sur_nez:1.28,pommettes_sur_nez:4.11,sn_st_sur_st_gn:.52,intercanthale_sur_fente:.98,tiers:[.359,.312,.329]},symetrie:`Modèle généré symétrique : écart gauche/droite nul par construction (une vraie personne présente toujours de légères asymétries).`},t=e=>e.toLocaleString(`fr-FR`,{maximumFractionDigits:1}),n=e=>e.toLocaleString(`fr-FR`,{minimumFractionDigits:2,maximumFractionDigits:2}),r=e=>Math.round(e*100)+` %`,i=e.ratios,a=e,o={resume:`Visage ovale : les pommettes sont le point le plus large (${t(e.largeur_pommettes)} mm), le front et la mâchoire sont plus étroits et le menton est arrondi. Peau claire semée de taches de rousseur, iris noisette, sourcils et cheveux brun foncé plaqués en arrière : un contraste élevé.`,traits:[[`Forme`,`Ovale. Hauteur ${n(i.hauteur_sur_largeur)} × la largeur ; front ${n(i.front_sur_pommettes)} et mâchoire ${n(i.machoire_sur_pommettes)} de la largeur des pommettes.`],[`Proportions`,`Tiers du visage : ${r(i.tiers[0])} / ${r(i.tiers[1])} / ${r(i.tiers[2])}. Le front est légèrement dominant ; le milieu et le bas sont proches.`],[`Contraste`,`Élevé : cheveux et sourcils brun foncé sur une peau claire.`],[`Teint`,`Clair ; le sous-ton reste à confirmer, il dépend de la lumière de la capture.`],[`Signe distinctif`,`Taches de rousseur denses sur le nez et le haut des joues.`]],relations:[{titre:`Un ovale équilibré à préserver`,texte:`Pommettes au point le plus large, front et mâchoire plus étroits : les règles de visagisme recommandent de ne pas déséquilibrer cet ovale (pas de volume excessif en haut, pas de contouring marqué, pas de monture trop large).`,zones:[`cheeks`,`forehead`,`jaw`,`hair`]},{titre:`Un contraste fort`,texte:`Sourcils et cheveux foncés encadrent une peau claire : ce contraste guide les couleurs de maquillage, de coloration et de monture.`,zones:[`brows`,`hair`,`eyes`]},{titre:`Une peau claire à protéger partout`,texte:`Les taches de rousseur se concentrent sur le nez et le haut des joues, les zones les plus exposées. Une seule protection solaire couvre le visage, le cou et les oreilles ; les lèvres ont leur baume protecteur.`,zones:[`nose`,`cheeks`,`neck`,`ears`,`mouth`]},{titre:`Un front dégagé par la coiffure`,texte:`Les cheveux plaqués découvrent tout le front, qui occupe déjà ${r(i.tiers[0])} de la hauteur du visage : c’est là que la coiffure a le plus d’effet.`,zones:[`forehead`,`hair`,`temples`]}],transversaux:[{titre:`Une routine peau unique`,texte:`Nettoyer, hydrater, protéger : les mêmes produits servent toutes les zones de peau, matin et soir.`,fiche:`routine-peau`},{titre:`Un geste d’entretien unique`,texte:`Une séance de gua sha suit tout le visage, du cou au front ; chaque zone en ouvre l’étape qui la concerne.`,fiche:`gua-sha`},{titre:`Trois fiches à donner aux pros`,texte:`Coiffeur, maquilleur et opticien : ce qui a été relevé et ce qu’il faut leur demander.`,fiche:`coiffeur`}]},s={nettoyant:{id:`nettoyant`,famille:`Soin`,type:`Nettoyant doux sans parfum`,texture:`Gel ou lait, matin et soir`,choisir:`Formule douce, non moussante ou peu moussante.`,eviter:`Savons décapants, parfums.`},ceramides:{id:`ceramides`,famille:`Soin`,type:`Crème hydratante légère aux céramides`,texture:`Gel-crème, visage et cou, matin et soir`,choisir:`Humectants (glycérine, acide hyaluronique) et céramides.`,eviter:`Textures trop riches si la peau brille en journée.`},spf50:{id:`spf50`,famille:`Soin`,type:`Protection solaire large spectre, indice 50`,texture:`Fluide léger, en dernière étape du matin`,choisir:`Large spectre, texture agréable à porter tous les jours.`,eviter:`Une quantité trop faible : couvrir visage, cou et oreilles.`},"baume-spf":{id:`baume-spf`,famille:`Soin`,type:`Baume à lèvres SPF 30 ou plus, filtres minéraux`,texture:`Stick, avant de sortir puis toutes les 2 h dehors`,choisir:`Oxyde de zinc ou dioxyde de titane, beurre de karité, céramides.`,eviter:`Parfum, menthol, camphre, eucalyptus, arômes (cannelle, agrumes, menthe).`},"baume-nuit":{id:`baume-nuit`,famille:`Soin`,type:`Baume ou onguent épais à base de vaseline`,texture:`Couche épaisse, le soir`,choisir:`Sans parfum.`,eviter:`Lanoline et menthol si la peau des lèvres réagit.`},huile:{id:`huile`,famille:`Soin`,type:`Huile végétale légère pour la glisse`,texture:`3 à 4 gouttes avant le gua sha ou le massage`},pierre:{id:`pierre`,famille:`Accessoire`,type:`Pierre de gua sha à bord lisse (quartz rose ou équivalent)`,texture:`Un bord long, un bord incurvé, une encoche`},"bb-creme":{id:`bb-creme`,famille:`Maquillage`,type:`BB crème, teinte proche de la carnation`,texture:`Une petite quantité (un petit pois), au doigt ou à l’éponge`,choisir:`Teinte au plus près de la peau, ni plus claire ni plus foncée.`,eviter:`Une couvrance qui masque les taches de rousseur.`},correcteur:{id:`correcteur`,famille:`Maquillage`,type:`Correcteur léger, teinte proche de la carnation`,texture:`Touches ciblées, estompées au doigt`},"blush-creme":{id:`blush-creme`,famille:`Maquillage`,type:`Blush crème pêche ou rose doux`,texture:`Crème, au doigt, haut sur la pommette`},enlumineur:{id:`enlumineur`,famille:`Maquillage`,type:`Enlumineur crème discret`,texture:`Une touche au doigt`},"gel-sourcils":{id:`gel-sourcils`,famille:`Maquillage`,type:`Gel sourcils transparent`,texture:`Brossé vers le haut, le matin`},"crayon-sourcils":{id:`crayon-sourcils`,famille:`Maquillage`,type:`Crayon sourcils brun foncé, mine fine`,texture:`Petits traits dans le sens du poil, seulement là où il manque`},"fard-noisette":{id:`fard-noisette`,famille:`Maquillage`,type:`Fard prune, bronze cuivré ou kaki, mat ou satiné`,texture:`Poudre ou crème, dans le pli de la paupière`},"liner-feutre":{id:`liner-feutre`,famille:`Maquillage`,type:`Eye-liner feutre pointe fine, brun ou noir`,texture:`Trait fin, au ras des cils`},mascara:{id:`mascara`,famille:`Maquillage`,type:`Mascara noir ou brun-noir`,texture:`Une couche, de la racine vers les pointes`},"rouge-levres":{id:`rouge-levres`,famille:`Maquillage`,type:`Rouge à lèvres cerise ou nude rosé`,texture:`Crème ou satiné`},demaquillant:{id:`demaquillant`,famille:`Soin`,type:`Eau micellaire ou démaquillant doux`,texture:`Le soir, seulement si maquillage`},shampoing:{id:`shampoing`,famille:`Cheveux`,type:`Shampoing doux`,texture:`Sur le cuir chevelu seulement, massé du bout des doigts`},"apres-shampoing":{id:`apres-shampoing`,famille:`Cheveux`,type:`Après-shampoing`,texture:`Longueurs et pointes seulement, jamais sur le cuir chevelu`},"creme-coiffante":{id:`creme-coiffante`,famille:`Cheveux`,type:`Crème ou gel coiffant léger, tenue souple`,texture:`Une noisette sur cheveux humides, peignée vers l’arrière`},elastiques:{id:`elastiques`,famille:`Accessoire`,type:`Élastiques sans métal (tissu ou spirale)`,texture:`Pour attacher sans casser ni tirer`},"taie-satin":{id:`taie-satin`,famille:`Accessoire`,type:`Taie d’oreiller en satin ou soie`,texture:`Limite le frottement la nuit`}},c=`Pas sur une peau irritée, une plaie, une poussée de boutons, ni juste après un acte esthétique. Pression légère : la peau rosit, elle ne rougit pas. Ne jamais appuyer sur l’avant du cou.`,l={"gua-sha":{id:`gua-sha`,titre:`Gua sha du visage`,outil:`Pierre à bord lisse`,preparation:`Visage propre, 3 à 4 gouttes d’huile, pierre presque à plat (15° de la peau).`,frequence:`2 à 3 fois par semaine, environ 6 minutes`,attention:c,etapes:[{titre:`Cou (préparation)`,de:`jaw`,vers:`neck`,prolonge:1.15,action:`Racler doucement le cou de haut en bas, sur les côtés.`,direction:`Vers le bas`,pression:`Légère à modérée`,angle:`15°`,duree:`1 min`},{titre:`Mâchoire et menton`,de:`chin`,vers:`jaw`,prolonge:1.7,action:`Racler du menton vers l’oreille, l’os de la mâchoire dans l’encoche.`,direction:`Vers l’oreille`,pression:`Légère à modérée`,angle:`15°`,duree:`1 min`},{titre:`Joues`,de:`nose`,vers:`cheeks`,prolonge:1.9,action:`Racler du nez vers l’oreille, sous la pommette, bord incurvé.`,direction:`Vers l’oreille`,pression:`Légère à modérée`,angle:`15°`,duree:`1 min`},{titre:`Sous les yeux`,de:`nose`,vers:`temples`,action:`Racler très doucement de l’intérieur vers la tempe.`,direction:`Vers les tempes`,pression:`Très légère`,angle:`15°`,duree:`30 s`},{titre:`Front`,de:`forehead`,vers:`temples`,prolonge:1.1,action:`Racler du centre du front vers les tempes, bord long.`,direction:`Vers les tempes`,pression:`Légère à modérée`,angle:`15°`,duree:`1 min`},{titre:`Sourcils`,de:`brows`,vers:`temples`,action:`Racler doucement le long des sourcils, de la tête vers la queue.`,direction:`Vers les tempes`,pression:`Très légère`,angle:`15°`,duree:`30 s`},{titre:`Cou (fin)`,de:`jaw`,vers:`neck`,prolonge:1.15,action:`Racler à nouveau le cou de haut en bas.`,direction:`Vers le bas`,pression:`Légère à modérée`,angle:`15°`,duree:`1 min`}]},massage:{id:`massage`,titre:`Massage du visage`,outil:`Les mains (ou un rouleau)`,preparation:`Visage propre, quelques gouttes d’huile ou la crème hydratante.`,frequence:`Le soir, environ 5 minutes`,attention:c,etapes:[{titre:`Front`,de:`forehead`,vers:`temples`,prolonge:1.1,action:`Balayer du centre vers les tempes, à plat avec les doigts.`,direction:`Vers les tempes`,pression:`Légère`,duree:`1 min`},{titre:`Sourcils`,de:`brows`,vers:`temples`,action:`Balayer doucement le long des sourcils.`,direction:`Vers les tempes`,pression:`Très légère`,duree:`30 s`},{titre:`Sous les yeux`,de:`nose`,vers:`temples`,action:`Balayer de l’intérieur vers les tempes, avec l’annulaire.`,direction:`Vers les tempes`,pression:`Très légère`,duree:`30 s`},{titre:`Joues`,de:`nose`,vers:`cheeks`,prolonge:1.9,action:`Balayer du nez vers les oreilles.`,direction:`Vers les oreilles`,pression:`Légère`,duree:`1 min`},{titre:`Mâchoire et menton`,de:`chin`,vers:`jaw`,prolonge:1.7,action:`Balayer du menton vers les oreilles.`,direction:`Vers les oreilles`,pression:`Légère`,duree:`1 min`},{titre:`Cou`,de:`jaw`,vers:`neck`,prolonge:1.15,action:`Balayer doucement de haut en bas.`,direction:`Vers le bas`,pression:`Légère`,duree:`1 min`}]},drainage:{id:`drainage`,titre:`Drainage lymphatique du visage`,outil:`Les mains`,preparation:`Visage propre, mains à plat, gestes lents.`,frequence:`Le matin, environ 3 minutes 30`,attention:c,etapes:[{titre:`Cou (préparation)`,de:`ears`,vers:`neck`,prolonge:1.2,action:`Masser doucement sous les oreilles et le long du cou.`,direction:`Vers le bas`,pression:`Légère`,duree:`30 s`},{titre:`Front`,de:`forehead`,vers:`temples`,prolonge:1.1,action:`Petits cercles au-dessus des sourcils, puis balayer vers les tempes.`,direction:`Vers les tempes`,pression:`Légère`,duree:`30 s`},{titre:`Sous les yeux`,de:`nose`,vers:`temples`,action:`Balayer doucement de l’intérieur vers les tempes.`,direction:`Vers les tempes`,pression:`Très légère`,duree:`30 s`},{titre:`Joues`,de:`nose`,vers:`cheeks`,prolonge:1.9,action:`Balayer du nez vers les oreilles.`,direction:`Vers les oreilles`,pression:`Légère`,duree:`30 s`},{titre:`Mâchoire et menton`,de:`chin`,vers:`jaw`,prolonge:1.7,action:`Balayer du menton vers les oreilles.`,direction:`Vers les oreilles`,pression:`Légère`,duree:`30 s`},{titre:`Cou (fin)`,de:`ears`,vers:`neck`,prolonge:1.2,action:`Masser à nouveau sous les oreilles, vers le bas.`,direction:`Vers le bas`,pression:`Légère`,duree:`30 s`},{titre:`Clavicules`,de:`neck`,vers:`neck`,prolonge:1.5,action:`Balayer doucement vers les clavicules.`,direction:`Vers le bas`,pression:`Légère`,duree:`30 s`}]}},u=n=>t(e[n])+` mm`,d={forehead:{titre:`Front`,accroche:`Hauteur, largeur et peau.`,resume:`Front haut et lisse, entièrement dégagé par la coiffure : ${r(i.tiers[0])} de la hauteur du visage.`,obs:[{id:`hauteur`,label:`Hauteur`,sens:`obs`,texte:`Front haut, du bord des cheveux à la racine du nez.`,mesure:`Trichion → nasion : ${u(`tiers_haut`)}, soit ${r(i.tiers[0])} de la hauteur du visage. Repère : un tiers (33 %).`,comprendre:`Le tiers supérieur dépasse légèrement les deux autres. Cheveux plaqués, rien ne le recouvre : c’est la partie du visage que l’on voit en premier.`,lie:[`hair`,`brows`],conseils:[{objectif:`Adoucir la hauteur du front`,proposition:`Une frange rideau légère`,lien:`Séparée au milieu, elle couvre le haut du front et retombe sur les côtés, sans ajouter de volume en hauteur (à éviter sur un ovale).`,application:`Demandez une frange rideau qui s’arrête à hauteur des pommettes ; elle se plaque aussi en arrière les jours de coiffure tirée.`,fiche:`coiffeur`},{objectif:`Garder le front dégagé`,proposition:`Une raie douce sur le côté`,lien:`Une raie décalée casse la ligne horizontale du front et le fait paraître moins haut, tout en gardant l’effet plaqué.`,application:`Raie à l’aplomb de la pointe du sourcil, longueurs peignées en arrière avec la crème coiffante.`,produit:`creme-coiffante`,fiche:`coiffeur`},{objectif:`Détendre le front`,proposition:`Gua sha du front, du centre vers les tempes`,lien:`Une grande surface lisse : la pierre glisse à plat, bord long.`,application:`Étape « Front » de la séance de gua sha.`,geste:`gua-sha`,etape:4,fiche:`gua-sha`,produits:[`huile`,`pierre`]}]},{id:`largeur`,label:`Largeur`,sens:`obs`,texte:`Front plus étroit que les pommettes, tempes légèrement creusées.`,mesure:`Largeur du front : ${u(`largeur_front`)}, soit ${n(i.front_sur_pommettes)} × la largeur des pommettes (${u(`largeur_pommettes`)}).`,comprendre:`Un front plus étroit que les pommettes fait partie de la définition du visage ovale.`,lie:[`cheeks`,`temples`],conseils:[{objectif:`Préserver l’ovale`,proposition:`Pas de contouring sur le front`,lien:`Les maquilleurs déconseillent le contouring marqué sur un ovale : il déséquilibre des proportions déjà harmonieuses.`,application:`Teint léger uniforme (BB crème) jusqu’à la racine des cheveux, sans ombre sur les tempes.`,produit:`bb-creme`,fiche:`maquillage`}]},{id:`peau`,label:`Peau`,sens:`obs`,texte:`Peau lisse, quelques taches de rousseur légères.`,comprendre:`Le front découvert prend la lumière comme le nez et les joues.`,lie:[`nose`,`cheeks`],conseils:[{objectif:`Protéger le front découvert`,proposition:`Prolonger la protection solaire jusqu’à la racine des cheveux`,lien:`Avec une coiffure plaquée, la lisière est exposée en permanence.`,application:`Même fluide que pour le reste du visage, appliqué jusqu’à la lisière et sur la raie.`,produit:`spf50`,fiche:`solaire`}]}]},temples:{titre:`Tempes`,accroche:`Transition vers les cheveux.`,resume:`Tempes légèrement creusées, ligne d’implantation nette et régulière.`,obs:[{id:`transition`,label:`Transition`,sens:`obs`,texte:`Légère dépression entre le front et la pommette, lisière des cheveux nette.`,comprendre:`Cheveux tirés en arrière, la tempe est visible : elle marque la limite haute de l’ovale.`,lie:[`forehead`,`hair`,`cheeks`],conseils:[{objectif:`Adoucir le creux des tempes`,proposition:`Quelques mèches libres devant l’oreille`,lien:`Des mèches qui encadrent le visage ajoutent de la largeur sur les côtés, ce que les coiffeurs recommandent pour un ovale.`,application:`Laisser deux fines mèches libres de chaque côté au moment d’attacher les cheveux.`,fiche:`coiffeur`},{objectif:`Un geste de fin de séance`,proposition:`Terminer le massage sur les tempes`,lien:`Toutes les étapes du visage remontent vers les tempes.`,application:`Étape « Front » du massage du visage : balayer jusqu’aux tempes, pression légère.`,geste:`massage`,etape:0,fiche:`massage`}]}]},brows:{titre:`Sourcils`,accroche:`Densité, position et forme.`,resume:`Sourcils brun foncé, fournis, arc doux, posés assez près de l’œil.`,obs:[{id:`densite`,label:`Densité et couleur`,sens:`obs`,texte:`Fournis et réguliers, brun foncé, comme les cheveux.`,comprendre:`Ils participent au contraste fort du visage et structurent le regard.`,lie:[`hair`,`eyes`],conseils:[{objectif:`Garder un sourcil naturel`,proposition:`Discipliner sans épaissir`,lien:`Sur un ovale, on recommande une forme naturelle et l’on évite les sourcils trop épais.`,application:`Brosser vers le haut avec le gel, puis lisser la queue vers la tempe.`,produit:`gel-sourcils`,fiche:`maquillage`}]},{id:`position`,label:`Position`,sens:`obs`,texte:`Sourcils posés près de l’œil, arche douce.`,mesure:`Écart vertical sourcil–œil : ${u(`oeil_sourcil`)}.`,comprendre:`Un sourcil bas raccourcit visuellement le front ; ici il équilibre un tiers supérieur un peu haut.`,lie:[`forehead`,`eyes`],conseils:[{objectif:`Ouvrir le regard`,proposition:`Prolonger légèrement la queue`,lien:`Une queue un peu plus longue étire l’œil en amande vers la tempe sans remonter le sourcil.`,application:`Quelques traits fins au crayon dans le prolongement de l’aile du nez et du coin externe de l’œil.`,produit:`crayon-sourcils`,fiche:`maquillage`},{objectif:`Détendre la zone`,proposition:`Gua sha le long des sourcils`,lien:`La zone est fine : pression très légère.`,application:`Étape « Sourcils » de la séance de gua sha.`,geste:`gua-sha`,etape:5,fiche:`gua-sha`,produits:[`huile`,`pierre`]}]}]},eyes:{titre:`Yeux`,accroche:`Forme, espacement, iris.`,resume:`Yeux en amande, espacement équilibré, iris noisette, cils fournis.`,obs:[{id:`forme`,label:`Forme et espacement`,sens:`obs`,texte:`Œil en amande, coin externe légèrement relevé, espacement équilibré.`,mesure:`Écart entre les yeux ${u(`intercanthale`)} ; largeur d’un œil ${u(`fente_palpebrale`)} (rapport ${n(i.intercanthale_sur_fente)}). Repère : 1 (canon orbital).`,comprendre:`L’écart entre les yeux est presque égal à la largeur d’un œil : l’espacement est équilibré, il n’y a rien à compenser.`,lie:[`nose`,`brows`],conseils:[{objectif:`Étirer l’amande`,proposition:`Un liner fin étiré vers la tempe`,lien:`Le coin externe relevé prolonge naturellement le trait.`,application:`Petit trait depuis le coin externe, dans le prolongement des cils inférieurs ; plus fin vers l’intérieur.`,produit:`liner-feutre`,fiche:`liner`}]},{id:`iris`,label:`Iris`,sens:`obs`,texte:`Iris noisette, mélange de brun doré et de vert.`,comprendre:`Les teintes opposées (prune, cuivré, kaki) font ressortir les reflets verts et dorés.`,lie:[`hair`],conseils:[{objectif:`Faire ressortir la couleur`,proposition:`Une ombre prune, bronze cuivré ou kaki dans le pli`,lien:`Ces teintes contrastent avec les reflets de l’iris noisette.`,application:`Estomper dans le pli de la paupière, puis une couche de mascara.`,produits:[`fard-noisette`,`mascara`],fiche:`liner`}]},{id:`contour`,label:`Contour de l’œil`,sens:`obs`,texte:`Légère ombre sous l’œil, visible sur le modèle ; elle peut venir de la lumière comme d’un début de cerne.`,comprendre:`La peau du contour de l’œil est la plus fine du visage : la fatigue et le manque de sommeil s’y voient en premier.`,lie:[`cheeks`],conseils:[{objectif:`Un regard reposé`,proposition:`Des nuits régulières et suffisantes`,lien:`Dans une étude, les personnes privées de sommeil avaient les yeux plus gonflés, des cernes plus sombres et une peau qui récupère moins bien.`,application:`Coucher et lever à heures fixes, 7 à 9 h par nuit ; écrans éteints une heure avant.`,famille:`Hygiène de vie`,preuve:`modérée`,source:{titre:`Does poor sleep quality affect skin ageing? (PubMed)`,url:`https://pubmed.ncbi.nlm.nih.gov/25266053/`},pour:[`peau`,`valeur`]},{objectif:`Dégonfler le matin`,proposition:`Drainage sous les yeux, pression très légère`,lien:`Les gestes vers les tempes aident à évacuer le gonflement du réveil.`,application:`Étape « Sous les yeux » du drainage du matin, à l’annulaire.`,geste:`drainage`,etape:2,fiche:`drainage`,pour:[`peau`]},{objectif:`Atténuer l’ombre`,proposition:`Une touche de correcteur, seulement au coin interne`,lien:`Une ombre légère se corrige sans masquer les taches de rousseur autour.`,application:`Tapoter au doigt dans le creux du coin interne, estomper vers l’extérieur.`,produit:`correcteur`,fiche:`maquillage`,pour:[`valeur`]}]},{id:`monture`,label:`Lunettes`,sens:`obs`,texte:`Yeux centrés, sourcils assez bas : la monture doit se poser à leur hauteur.`,comprendre:`Pour un ovale, les opticiens recommandent une monture de largeur et hauteur moyennes, centrée sur le nez, alignée sur les sourcils.`,lie:[`nose`,`ears`],conseils:[{objectif:`Choisir une monture`,proposition:`Ronde, ovale ou rectangulaire, de largeur moyenne`,lien:`L’ovale accepte la plupart des formes ; seules les montures trop larges le déséquilibrent.`,application:`Le haut de la monture suit la ligne des sourcils sans la dépasser ; couleur foncée ou écaille pour répondre au contraste.`,fiche:`opticien`}]}]},nose:{titre:`Nez`,accroche:`Arête, pointe, largeur, peau.`,resume:`Arête droite et fine, pointe arrondie, taches de rousseur denses.`,obs:[{id:`arete`,label:`Arête`,sens:`obs`,texte:`Droite et fine, sans bosse visible de face.`,mesure:`Longueur du nez (nasion → subnasale) : ${u(`longueur_nez`)}.`,comprendre:`Une arête fine attire peu l’œil : le nez reste discret au centre du visage.`,conseils:[{objectif:`Mettre l’arête en valeur`,proposition:`Une touche de lumière au milieu de l’arête`,lien:`Une arête fine renvoie bien la lumière.`,application:`Enlumineur tapoté au doigt, sans descendre jusqu’à la pointe.`,produit:`enlumineur`,fiche:`maquillage`}]},{id:`largeur`,label:`Largeur`,sens:`obs`,texte:`Ailes du nez un peu plus larges que l’écart entre les yeux.`,mesure:`Largeur du nez ${u(`largeur_nez`)} ; écart entre les yeux ${u(`intercanthale`)} (rapport ${n(i.nez_sur_intercanthale)}). Repère : 1 (canon orbitonasal). Pommettes / nez : ${n(i.pommettes_sur_nez)} (repère : 4).`,comprendre:`Par rapport à la largeur du visage, le nez est dans la proportion de référence ; c’est seulement l’écart des yeux, étroit, qui le fait paraître un peu plus large.`,lie:[`eyes`,`cheeks`],conseils:[{objectif:`Garder un profil doux`,proposition:`Pas de contouring du nez`,lien:`La proportion avec le visage est juste ; un contouring marqué déséquilibrerait l’ovale.`,application:`Teint léger uniforme, aucune ombre sur les côtés du nez.`,produit:`bb-creme`,fiche:`maquillage`}]},{id:`pointe`,label:`Pointe et projection`,sens:`obs`,texte:`Pointe arrondie, légèrement relevée, douce de profil.`,mesure:`Projection de la pointe : ${u(`projection_nez`)}.`,comprendre:`Une pointe arrondie s’accorde aux autres courbes du visage (pommettes, menton).`,lie:[`chin`]},{id:`peau`,label:`Peau`,sens:`obs`,texte:`Zone la plus dense en taches de rousseur.`,comprendre:`Le nez reçoit le plus de lumière du visage : le soleil y renforce d’abord les taches.`,lie:[`cheeks`,`forehead`],conseils:[{objectif:`Limiter l’accentuation des taches`,proposition:`Protection solaire, en priorité sur le nez`,lien:`C’est la zone la plus exposée.`,application:`Couche généreuse le matin ; repasser sur le nez en premier lors du renouvellement.`,produit:`spf50`,fiche:`solaire`},{objectif:`Garder les taches visibles`,proposition:`Un teint léger plutôt que couvrant`,lien:`Les taches font partie de la signature du visage.`,application:`BB crème en petite quantité, correcteur seulement là où c’est utile.`,produits:[`bb-creme`,`correcteur`],fiche:`maquillage`}]},{id:`grain`,label:`Grain`,sens:`doute`,texte:`Grain un peu plus marqué sur les ailes : lumière ou texture, à confirmer.`}]},cheeks:{titre:`Joues`,accroche:`Pommettes, volume et peau.`,resume:`Pommettes hautes au point le plus large du visage, joues pleines, taches de rousseur sur le haut.`,obs:[{id:`pommettes`,label:`Pommettes`,sens:`obs`,texte:`Hautes et douces : c’est le point le plus large du visage.`,mesure:`Largeur aux pommettes : ${u(`largeur_pommettes`)} (front ${u(`largeur_front`)}, mâchoire ${u(`largeur_machoire`)}).`,comprendre:`Des pommettes plus larges que le front et la mâchoire définissent l’ovale ; elles accrochent la lumière.`,lie:[`forehead`,`jaw`],conseils:[{objectif:`Souligner les pommettes`,proposition:`Blush posé haut, étiré vers la tempe`,lien:`Prolonge le mouvement naturel de l’os sans contouring marqué.`,application:`Sourire légèrement, poser sur le haut de la pommette, estomper vers la tempe, jamais vers le nez.`,produit:`blush-creme`,fiche:`blush`},{objectif:`Un visage détendu`,proposition:`Gua sha des joues, du nez vers l’oreille`,lien:`Le geste suit la ligne de l’os, sous la pommette.`,application:`Étape « Joues » de la séance de gua sha.`,geste:`gua-sha`,etape:2,fiche:`gua-sha`,produits:[`huile`,`pierre`]}]},{id:`volume`,label:`Volume`,sens:`obs`,texte:`Joues pleines, transition douce vers la mâchoire.`,comprendre:`Des joues pleines et une transition douce donnent un ovale sans angle.`,lie:[`jaw`,`hair`],conseils:[{objectif:`Équilibrer en coiffure`,proposition:`Du volume sur les côtés plutôt qu’en haut`,lien:`Pour un ovale, les coiffeurs recommandent des volumes sur les côtés et déconseillent les coupes trop volumineuses en haut.`,application:`Jours de cheveux lâchés : mise en pli souple à hauteur des pommettes.`,fiche:`coiffeur`}]},{id:`peau`,label:`Peau`,sens:`obs`,texte:`Claire, grain fin, taches de rousseur sur le tiers supérieur.`,comprendre:`Une peau claire au grain fin se dessèche et marque vite au soleil ; le type de peau (sèche, mixte, normale) reste à confirmer par la personne.`,lie:[`nose`,`neck`,`forehead`],conseils:[{objectif:`Garder la peau souple`,proposition:`Nettoyer doucement, hydrater matin et soir`,lien:`Une peau sans signe particulier n’a besoin que d’une routine simple : les dermatologues recommandent nettoyer, hydrater, protéger.`,application:`Nettoyant doux, puis une noisette de crème du centre vers l’extérieur, cou compris.`,produits:[`nettoyant`,`ceramides`],fiche:`routine-peau`},{objectif:`Préserver le teint`,proposition:`Protection solaire chaque matin`,lien:`Les taches du haut des joues se renforcent au soleil.`,application:`En dernière étape du matin, après la crème.`,produit:`spf50`,fiche:`solaire`}]},{id:`rougeurs`,label:`Rougeurs`,sens:`doute`,texte:`Légère coloration sur les pommettes : lumière ou teint, à confirmer.`}]},mouth:{titre:`Bouche et lèvres`,accroche:`Largeur, volume, soin.`,resume:`Lèvres pleines, arc de Cupidon marqué, bouche plutôt étroite par rapport au nez.`,obs:[{id:`largeur`,label:`Largeur`,sens:`obs`,texte:`Bouche plutôt étroite, commissures proches des ailes du nez.`,mesure:`Largeur de la bouche ${u(`largeur_bouche`)} = ${n(i.bouche_sur_nez)} × la largeur du nez. Repère : 1,5 (canon naso-oral).`,comprendre:`La bouche est un peu moins large que la référence : le regard se porte sur le volume des lèvres plutôt que sur leur largeur.`,lie:[`nose`],conseils:[{objectif:`Élargir visuellement la bouche`,proposition:`Couleur posée jusqu’aux commissures`,lien:`Une teinte qui va bien jusqu’aux coins prolonge la ligne de la bouche.`,application:`Poser la couleur au centre, presser les lèvres, puis étirer au doigt jusqu’aux commissures.`,produit:`rouge-levres`,fiche:`maquillage`}]},{id:`volume`,label:`Volume et contour`,sens:`obs`,texte:`Lèvres pleines, arc de Cupidon net, teinte rose naturelle.`,mesure:`Nez → bouche ${u(`sn_st`)} ; bouche → menton ${u(`st_gn`)} (rapport ${n(i.sn_st_sur_st_gn)}). Repère : 0,62.`,comprendre:`La lèvre supérieure est courte par rapport au bas du visage : l’arc de Cupidon se voit bien.`,lie:[`chin`],conseils:[{objectif:`Souligner l’arc de Cupidon`,proposition:`Rouge cerise ou nude rosé, contour net`,lien:`Un arc net se dessine sans crayon.`,application:`Dessiner l’arc avec le biseau du rouge, estomper vers les coins.`,produit:`rouge-levres`,fiche:`levres`}]},{id:`soin`,label:`Soin des lèvres`,sens:`obs`,texte:`Lèvres claires, sans protection naturelle.`,comprendre:`La peau des lèvres n’a presque pas de mélanine : elle marque au soleil et se dessèche au froid.`,lie:[`nose`,`cheeks`],conseils:[{objectif:`Protéger le jour`,proposition:`Baume SPF 30 avant de sortir`,lien:`La protection solaire du visage ne couvre pas les lèvres.`,application:`Avant de sortir, puis toutes les 2 heures dehors et après avoir mangé.`,produit:`baume-spf`,fiche:`levres`},{objectif:`Réparer la nuit`,proposition:`Couche épaisse de baume le soir`,lien:`Une couche occlusive limite la perte d’eau pendant la nuit.`,application:`En dernier geste du soir, après la crème.`,produit:`baume-nuit`,fiche:`levres`}]}]},chin:{titre:`Menton`,accroche:`Forme, hauteur, axe.`,resume:`Menton arrondi, dans l’axe ; le bas du visage est dans la proportion de référence.`,obs:[{id:`forme`,label:`Forme`,sens:`obs`,texte:`Menton arrondi, centré, sans fossette.`,mesure:`Bas du visage (subnasale → menton) : ${u(`tiers_bas`)}, soit ${r(i.tiers[2])} de la hauteur. Repère : 33 %.`,comprendre:`Le tiers inférieur est dans la proportion de référence ; la forme arrondie termine l’ovale en douceur.`,lie:[`jaw`,`mouth`],conseils:[{objectif:`Dessiner le bas du visage`,proposition:`Gua sha du menton vers l’oreille`,lien:`Le geste part du centre du menton et suit l’os.`,application:`Étape « Mâchoire et menton » de la séance de gua sha.`,geste:`gua-sha`,etape:1,fiche:`gua-sha`,produits:[`huile`,`pierre`]}]}]},jaw:{titre:`Mâchoire`,accroche:`Largeur et angle.`,resume:`Mâchoire douce et étroite, angle peu marqué.`,obs:[{id:`angle`,label:`Largeur et angle`,sens:`obs`,texte:`Angle peu marqué, ligne douce jusqu’au menton.`,mesure:`Largeur aux angles ${u(`largeur_machoire`)}, soit ${n(i.machoire_sur_pommettes)} × la largeur des pommettes.`,comprendre:`Une mâchoire plus étroite que les pommettes ferme l’ovale ; elle ne demande ni ombre ni volume.`,lie:[`cheeks`,`chin`,`hair`],conseils:[{objectif:`Une ligne plus nette`,proposition:`Gua sha le long de l’os de la mâchoire`,lien:`L’encoche de la pierre épouse l’os ; c’est la même étape que le menton.`,application:`Étape « Mâchoire et menton » de la séance de gua sha.`,geste:`gua-sha`,etape:1,fiche:`gua-sha`,produits:[`huile`,`pierre`]},{objectif:`Préserver l’ovale`,proposition:`Pas de contouring de la mâchoire`,lien:`Sur un ovale, le contouring marqué déséquilibre plus qu’il ne sculpte.`,application:`Un voile de blush sur la pommette suffit à structurer.`,produit:`blush-creme`,fiche:`maquillage`}]}]},ears:{titre:`Oreilles`,accroche:`Port, dégagement.`,resume:`Oreilles proches de la tête, entièrement dégagées par la coiffure plaquée.`,obs:[{id:`port`,label:`Port`,sens:`obs`,texte:`Oreilles proches de la tête, lobes visibles.`,comprendre:`Coiffure tirée en arrière, les oreilles sont exposées en permanence et portent les branches des lunettes.`,lie:[`hair`,`eyes`],conseils:[{objectif:`Ne pas oublier les oreilles`,proposition:`Les inclure dans la protection solaire`,lien:`Avec les cheveux plaqués, elles ne sont plus abritées.`,application:`Le reste de fluide des mains sur le haut et l’arrière de l’oreille.`,produit:`spf50`,fiche:`solaire`}]}]},neck:{titre:`Cou`,accroche:`Longueur, peau.`,resume:`Cou long et fin, peau claire comme le visage.`,obs:[{id:`longueur`,label:`Longueur et port`,sens:`obs`,texte:`Cou long et fin, port droit.`,comprendre:`Une coiffure plaquée et attachée bas met le cou en valeur.`,lie:[`hair`,`jaw`],conseils:[{objectif:`Traiter le cou comme le visage`,proposition:`Crème et protection solaire jusqu’au décolleté`,lien:`Même peau, même exposition : les mêmes produits suffisent.`,application:`Prolonger chaque soin du visage vers le bas, en lissant du bas vers le haut.`,produits:[`ceramides`,`spf50`],fiche:`routine-peau`},{objectif:`Ouvrir et fermer la séance`,proposition:`Gua sha du cou, de haut en bas`,lien:`La séance commence et se termine par le cou, vers les clavicules.`,application:`Étape « Cou (préparation) » de la séance de gua sha.`,geste:`gua-sha`,etape:0,fiche:`gua-sha`,produits:[`huile`,`pierre`]},{objectif:`Dégonfler le matin`,proposition:`Drainage du visage`,lien:`Toutes les étapes du drainage descendent vers le cou et les clavicules.`,application:`Séquence de drainage du matin, mains à plat.`,geste:`drainage`,etape:0,fiche:`drainage`}]}]},hair:{titre:`Cheveux`,accroche:`Nature, coiffage, entretien.`,resume:`Cheveux brun foncé, lisses, plaqués en arrière et attachés bas sur la nuque.`,obs:[{id:`coiffage`,label:`Coiffage`,sens:`obs`,texte:`Plaqués en arrière, sans raie, attachés bas sur la nuque.`,comprendre:`Un coiffage plaqué dégage entièrement l’ovale. Il ajoute peu de volume en haut, ce qui convient à ce visage ; il découvre aussi un front déjà haut.`,lie:[`forehead`,`temples`,`ears`],conseils:[{objectif:`Garder le plaqué, l’adoucir`,proposition:`Chignon bas légèrement défait, mèches qui encadrent le visage`,lien:`Des mèches libres apportent la largeur sur les côtés recommandée pour un ovale.`,application:`Crème coiffante peignée en arrière, attache basse avec un élastique sans métal, deux mèches libres devant les oreilles.`,produits:[`creme-coiffante`,`elastiques`],fiche:`coiffeur`},{objectif:`Changer de coupe`,proposition:`Hush cut ou lob avec frange rideau`,lien:`Longueurs dégradées et frange rideau : volume sur les côtés, front adouci, aucun volume en hauteur.`,application:`À montrer au coiffeur avec la fiche ; se coiffe encore en arrière les jours de chignon.`,fiche:`coiffeur`}]},{id:`tension`,label:`Coiffure tirée`,sens:`obs`,texte:`Coiffure tirée et attachée tous les jours.`,comprendre:`Attention : les coiffures trop serrées (chignons, tresses) répétées peuvent fragiliser la lisière, jusqu’à une perte de cheveux de traction.`,lie:[`forehead`,`temples`],conseils:[{objectif:`Protéger la lisière`,proposition:`Attacher sans serrer et varier la position`,lien:`C’est la tension répétée au même endroit qui fragilise la lisière des tempes et du front.`,application:`Élastique sans métal, attache un peu plus haute ou plus basse selon les jours, nuits cheveux détachés sur taie en satin.`,produits:[`elastiques`,`taie-satin`],fiche:`cheveux`}]},{id:`nature`,label:`Nature et entretien`,sens:`obs`,texte:`Cheveux lisses, fibre moyenne, longueur mi-longue.`,comprendre:`Des longueurs souvent attachées et peignées ont besoin d’être démêlées en douceur.`,lie:[`neck`],conseils:[{objectif:`Des longueurs souples`,proposition:`Shampoing sur le cuir chevelu, après-shampoing sur les longueurs`,lien:`Chaque produit sur sa zone : le cuir chevelu reste léger, les longueurs se démêlent.`,application:`Rincer à l’eau tiède, démêler des pointes vers les racines avec un peigne à dents larges, sécher sans frotter.`,produits:[`shampoing`,`apres-shampoing`],fiche:`cheveux`}]},{id:`couleur`,label:`Couleur`,sens:`obs`,texte:`Brun foncé uniforme, reflets froids.`,comprendre:`La couleur crée le contraste fort avec la peau claire ; garder une teinte profonde préserve ce contraste.`,lie:[`brows`,`eyes`],conseils:[{objectif:`Garder le contraste`,proposition:`Rester dans les bruns profonds`,lien:`Une teinte trop claire effacerait le contraste qui structure le visage.`,application:`Si coloration : chocolat ou brun froid, à voir avec le coloriste (fiche coiffeur).`,fiche:`coiffeur`}]}]}},f=[{quand:`Matin`,produit:`nettoyant`,action:`Laver le visage à l’eau tiède.`},{quand:`Matin`,geste:`drainage`,action:`Drainage du visage, environ 3 min 30 (facultatif).`},{quand:`Matin`,produit:`ceramides`,action:`Hydrater visage et cou.`},{quand:`Matin`,produit:`spf50`,action:`Protéger visage, cou, oreilles et lisière des cheveux.`},{quand:`Matin`,produit:`baume-spf`,action:`Protéger les lèvres avant de sortir.`},{quand:`Matin`,produit:`creme-coiffante`,action:`Coiffer en arrière, attacher sans serrer.`},{quand:`Dehors`,produit:`baume-spf`,action:`Renouveler le baume toutes les 2 heures et après les repas.`},{quand:`Dehors`,produit:`spf50`,action:`Renouveler la protection en exposition prolongée, nez en premier.`},{quand:`Soir`,produit:`demaquillant`,action:`Démaquiller si maquillage.`},{quand:`Soir`,produit:`nettoyant`,action:`Laver le visage.`},{quand:`Soir`,geste:`massage`,action:`Massage du visage, environ 5 min.`},{quand:`Soir`,produit:`ceramides`,action:`Hydrater visage et cou.`},{quand:`Soir`,produit:`baume-nuit`,action:`Couche épaisse de baume sur les lèvres.`},{quand:`Soir`,produit:`taie-satin`,action:`Dormir cheveux détachés.`},{quand:`Chaque semaine`,geste:`gua-sha`,action:`Séance de gua sha, 2 à 3 fois, environ 6 min.`},{quand:`Chaque semaine`,produit:`shampoing`,action:`Lavage des cheveux selon le besoin, puis après-shampoing sur les longueurs.`}],p=[{id:`coiffeur`,usage:`Coiffure`,pro:`Coiffeur`,titre:`Fiche pour votre coiffeur`,duree:`À montrer au rendez-vous`,zones:[`hair`,`forehead`,`temples`,`cheeks`],pourquoi:`Visage ovale (hauteur ${n(i.hauteur_sur_largeur)} × la largeur), pommettes au point le plus large, front haut (${r(i.tiers[0])} de la hauteur), cheveux brun foncé lisses, portés plaqués et attachés bas.`,etapes:[`Objectif : garder l’ovale équilibré ; ajouter du volume sur les côtés, pas en hauteur.`,`Adoucir le front : frange rideau séparée au milieu, longueur aux pommettes, qui se plaque aussi en arrière.`,`Coupes proposées : hush cut (dégradé léger, mèches qui encadrent le visage) ou lob avec frange rideau.`,`Coiffages adaptés : chignon bas légèrement défait, demi-attaché, raie douce sur le côté.`,`Couleur : rester dans les bruns profonds (chocolat, brun froid) pour garder le contraste avec la peau claire.`,`À éviter : coupes volumineuses sur le dessus ; coiffures très serrées tous les jours (lisière fragilisée).`]},{id:`maquillage`,usage:`Maquillage`,pro:`Maquilleur`,titre:`Fiche pour votre maquilleur`,duree:`Maquillage de jour, 10 min`,zones:[`cheeks`,`eyes`,`brows`,`nose`,`mouth`],pourquoi:`Ovale équilibré, peau claire à taches de rousseur à garder visibles, iris noisette, sourcils foncés fournis, lèvres pleines.`,etapes:[`Teint : BB crème en petite quantité, correcteur seulement où c’est utile ; laisser les taches visibles.`,`Pas de contouring marqué (front, nez, mâchoire) : il déséquilibre un ovale.`,`Pommettes : blush crème pêche ou rose doux, haut et étiré vers la tempe ; touche d’enlumineur sur l’arête du nez.`,`Yeux : ombre prune, bronze cuivré ou kaki dans le pli ; liner fin étiré ; mascara.`,`Sourcils : gel transparent, queue prolongée de quelques traits ; ne pas épaissir.`,`Lèvres : cerise ou nude rosé, couleur jusqu’aux commissures ; arc dessiné au biseau.`,`Fixer : brume fixatrice à 20–30 cm.`]},{id:`opticien`,usage:`Lunettes`,pro:`Opticien`,titre:`Fiche pour votre opticien`,duree:`Au choix de la monture`,zones:[`eyes`,`nose`,`ears`],pourquoi:`Visage ovale ; écart des yeux ${u(`intercanthale`)}, largeur d’un œil ${u(`fente_palpebrale`)}, nez ${u(`largeur_nez`)}, sourcils assez bas.`,etapes:[`Formes : ronde, ovale ou rectangulaire ; la plupart conviennent à un ovale.`,`Taille : largeur et hauteur moyennes ; éviter les montures trop larges.`,`Position : centrée sur le nez, le haut de la monture aligné sur les sourcils.`,`Couleur : foncée ou écaille, en accord avec les cheveux et sourcils brun foncé.`,`Branches : oreilles proches de la tête, prévoir un ajustement léger derrière l’oreille.`]},{id:`routine-peau`,usage:`Entretien`,titre:`Routine peau du matin et du soir`,duree:`3 min le matin, 3 min le soir`,zones:[`cheeks`,`nose`,`forehead`,`neck`],pourquoi:`Peau claire au grain fin, taches de rousseur ; type de peau à confirmer, routine de base d’une peau sans signe particulier.`,etapes:[`Matin : nettoyant doux → crème hydratante (visage et cou) → protection solaire en dernière étape.`,`Soir : démaquillant si maquillage → nettoyant doux → crème hydratante → baume épais sur les lèvres.`,`Garder la routine simple ; si la peau tiraille, choisir une crème plus riche ; si elle brille, une texture plus légère.`],attention:`Arrêter un produit qui pique ou brûle. Une rougeur persistante ou une tache qui change se montre à un professionnel de santé.`},{id:`solaire`,usage:`Produits`,titre:`Protection solaire`,duree:`1 min par jour`,zones:[`nose`,`cheeks`,`forehead`,`neck`,`ears`],pourquoi:`Peau claire, taches de rousseur, front et oreilles découverts par la coiffure.`,etapes:[`Indice élevé, large spectre, texture agréable à porter tous les jours.`,`Le matin en dernière étape : visage, nez en priorité, lisière des cheveux, oreilles, cou.`,`En extérieur prolongé : renouveler, nez en premier.`,`Les lèvres ont leur propre baume SPF 30.`]},{id:`levres`,usage:`Entretien`,titre:`Soin et couleur des lèvres`,duree:`1 min`,zones:[`mouth`],pourquoi:`Lèvres claires et pleines, arc de Cupidon net.`,etapes:[`Matin : baume non irritant ; avant de sortir, baume SPF 30 ou plus.`,`Dehors : renouveler toutes les 2 heures et après avoir mangé ou bu.`,`Couleur : poser au centre, presser, étirer jusqu’aux commissures ; arc au biseau du rouge.`,`Soir : couche épaisse de baume à la vaseline.`],attention:`Ne pas lécher, mordre ou arracher la peau des lèvres. Arrêter un produit qui brûle ou picote. Des lèvres gercées plus de 2 à 3 semaines se montrent à un professionnel de santé.`},{id:`cheveux`,usage:`Coiffure`,titre:`Entretien des cheveux plaqués`,duree:`10 min au lavage`,zones:[`hair`],pourquoi:`Cheveux lisses mi-longs, coiffés en arrière et attachés tous les jours.`,etapes:[`Shampoing sur le cuir chevelu seulement, massé du bout des doigts, sans les ongles.`,`Rincer à l’eau tiède, pas chaude.`,`Après-shampoing sur les longueurs et pointes seulement.`,`Démêler avec les doigts ou un peigne à dents larges, des pointes vers les racines.`,`Sécher en pressant avec une serviette microfibre ou un tee-shirt, sans frotter.`,`Attacher sans serrer avec un élastique sans métal ; varier la hauteur de l’attache ; dormir cheveux détachés sur une taie en satin.`],attention:`Les coiffures très serrées répétées peuvent fragiliser la lisière ; une perte de cheveux visible se montre à un professionnel de santé.`},{id:`gua-sha`,usage:`Entretien`,titre:`Séance de gua sha`,duree:`Environ 6 min, 2 à 3 fois par semaine`,zones:[`neck`,`jaw`,`chin`,`cheeks`,`eyes`,`forehead`,`brows`],pourquoi:`Un ovale doux : la pierre suit les lignes des pommettes et de la mâchoire, du cou jusqu’au front.`,etapes:[],attention:c},{id:`massage`,usage:`Entretien`,titre:`Massage du visage`,duree:`Environ 5 min, le soir`,zones:[`forehead`,`brows`,`eyes`,`cheeks`,`jaw`,`neck`],pourquoi:`Le même trajet que le gua sha, avec les mains, au moment d’appliquer la crème du soir.`,etapes:[],attention:c},{id:`drainage`,usage:`Entretien`,titre:`Drainage du visage`,duree:`Environ 3 min 30, le matin`,zones:[`neck`,`forehead`,`eyes`,`cheeks`,`jaw`],pourquoi:`Des gestes très légers vers le cou et les clavicules, à faire au réveil.`,etapes:[],attention:c},{id:`liner`,usage:`Maquillage`,titre:`Liner étiré et ombres pour iris noisette`,duree:`5 min`,zones:[`eyes`],pourquoi:`Œil en amande au coin relevé, iris noisette, espacement équilibré.`,etapes:[`Regarder droit devant : repérer le prolongement des cils inférieurs vers la tempe.`,`Tracer un petit trait depuis le coin externe dans ce prolongement.`,`Relier la pointe au milieu de la paupière, au ras des cils.`,`Remplir en gardant le trait fin vers l’intérieur de l’œil.`,`Estomper une ombre prune, bronze cuivré ou kaki dans le pli ; une couche de mascara.`]},{id:`blush`,usage:`Maquillage`,titre:`Blush et lumière sur pommettes hautes`,duree:`3 min`,zones:[`cheeks`,`nose`],pourquoi:`Pommettes au point le plus large du visage, taches de rousseur à garder visibles.`,etapes:[`Sourire légèrement pour repérer le haut de la pommette.`,`Poser le blush sur ce point, estomper vers la tempe.`,`Une touche d’enlumineur au-dessus, sur l’os, et au milieu de l’arête du nez.`,`Tapoter sans frotter pour garder les taches visibles.`]}];for(let[e,t]of[[`gua-sha`,`gua-sha`],[`massage`,`massage`],[`drainage`,`drainage`]]){let n=l[t];p.find(t=>t.id===e).etapes=[n.preparation,...n.etapes.map(e=>`${e.titre} : ${e.action} ${e.direction}, pression ${e.pression.toLowerCase()}${e.angle?`, pierre à `+e.angle:``}, ${e.duree}.`),`Fréquence : `+n.frequence+`.`]}var m=e=>p.find(t=>t.id===e),h={soleil:{titre:`Sunscreen and prevention of skin aging, essai randomisé (Annals of Internal Medicine, 2013)`,url:`https://www.acponline.org/acp-newsroom/daily-sunscreen-use-slows-skin-aging-even-in-middle-age`},sommeil:{titre:`Does poor sleep quality affect skin ageing? (Clinical and Experimental Dermatology, 2015)`,url:`https://pubmed.ncbi.nlm.nih.gov/25266053/`},alimentation:{titre:`Dietary interventions in skin ageing, méta-analyse (J Physiol Anthropol, 2025)`,url:`https://www.ncbi.nlm.nih.gov/pmc/articles/PMC12577306/`},complements:{titre:`Dietary supplements for skin photoaging, méta-analyse d’essais (Front Med, 2025)`,url:`https://pubmed.ncbi.nlm.nih.gov/40761858/`}};{let e=d.cheeks.obs.find(e=>e.id===`peau`).conseils.find(e=>e.produit===`spf50`);e.lien=`Les taches du haut des joues se renforcent au soleil. Et dans un essai de 4 ans et demi, les personnes qui mettaient une crème solaire chaque jour avaient 24 % de vieillissement visible de la peau en moins.`,e.famille=`Soin`,e.preuve=`forte`,e.source=h.soleil,e.pour=[`peau`,`valeur`],d.cheeks.obs.find(e=>e.id===`peau`).conseils.push({objectif:`Nourrir la peau de l’intérieur`,proposition:`Une assiette riche en végétaux colorés`,lien:`Une méta-analyse de 2025 conclut que l’alimentation agit sur les rides, l’hydratation et la barrière de la peau ; c’est un levier modifiable du vieillissement cutané.`,application:`Chaque jour : légumes et fruits de plusieurs couleurs, une source d’oméga-3 (poissons gras, noix), de l’eau ; les sucres rapides avec modération.`,famille:`Hygiène de vie`,preuve:`modérée`,source:h.alimentation,pour:[`peau`]},{objectif:`Choisir ses compléments avec discernement`,proposition:`Privilégier l’assiette aux gélules`,lien:`Parmi les compléments testés contre le vieillissement dû au soleil, seuls les polyphénols ont montré un effet ; l’acide hyaluronique, le lycopène et les caroténoïdes n’en ont pas montré.`,application:`Thé vert, cacao, baies et fruits rouges apportent des polyphénols ; aucun complément ne remplace la protection solaire.`,famille:`Hygiène de vie`,preuve:`modérée`,source:h.complements,pour:[`peau`]}),d.nose.obs.find(e=>e.id===`peau`).conseils.push({objectif:`Surveiller ses taches`,proposition:`Montrer à un dermatologue toute tache qui change`,lien:`Les taches de rousseur sont normales et stables ; une tache qui change de forme, de couleur ou de taille doit être vue par un professionnel.`,application:`Un coup d’œil chaque mois devant le miroir ; rendez-vous chez le dermatologue au moindre changement.`,famille:`Chez le pro`,pour:[`peau`]})}var g={"forehead.hauteur":`Un front haut donne un air ouvert et lumineux. Vous pouvez l’assumer tel quel, ou l’adoucir avec une frange rideau ou une raie sur le côté.`,"forehead.largeur":`Votre front, plus étroit que les pommettes, dessine le haut de l’ovale : il n’a besoin ni d’ombre ni de lumière en plus.`,"forehead.peau":`Une peau lisse et claire, qui se met en valeur avec un teint léger et une bonne protection.`,"temples.transition":`Des mèches libres ou un volume léger sur les côtés adoucissent le creux des tempes.`,"brows.densite":`Des sourcils fournis et foncés sont un atout : ils structurent le regard sans maquillage. Il suffit de les discipliner.`,"brows.position":`Vos sourcils posés près de l’œil équilibrent un front haut ; une queue un peu plus longue ouvre le regard.`,"eyes.forme":`Des yeux en amande bien espacés : tout leur va, et un trait fin étiré vers la tempe les souligne naturellement.`,"eyes.iris":`L’iris noisette ressort avec les teintes prune, bronze cuivré ou kaki.`,"eyes.contour":`Un regard reposé passe d’abord par le sommeil ; une touche de correcteur fait le reste.`,"eyes.monture":`Votre ovale porte la plupart des montures : ronde, ovale ou rectangulaire, de taille moyenne, alignée sur vos sourcils.`,"nose.arete":`Une arête fine et droite : une touche de lumière au centre suffit à la mettre en valeur.`,"nose.largeur":`Votre nez est dans la proportion de référence par rapport au visage : rien à corriger, surtout pas de contouring.`,"nose.pointe":`Une pointe arrondie qui répond à vos pommettes et à votre menton : un profil tout en douceur.`,"nose.peau":`Vos taches de rousseur sont une signature : on les protège du soleil et on les laisse visibles.`,"cheeks.pommettes":`Vos pommettes hautes sont votre point fort : un blush posé haut et étiré vers la tempe les révèle.`,"cheeks.volume":`Des joues pleines et douces, que l’on équilibre avec du volume sur les côtés plutôt qu’en hauteur.`,"cheeks.peau":`Une peau claire au grain fin, qui gagne à une routine simple : nettoyer, hydrater, protéger. Et le soleil, le sommeil et l’assiette comptent autant que les crèmes.`,"mouth.largeur":`Une bouche plutôt étroite se met en valeur avec une couleur posée jusqu’aux commissures.`,"mouth.volume":`Des lèvres pleines et un arc de Cupidon net : un rouge cerise ou un nude rosé les dessine sans crayon.`,"mouth.soin":`Des lèvres claires, à protéger du soleil le jour et à nourrir la nuit.`,"chin.forme":`Un menton arrondi et centré qui termine l’ovale en douceur ; il n’a besoin de rien de plus.`,"jaw.angle":`Une mâchoire douce et étroite : elle se dessine avec un geste de gua sha, sans maquillage.`,"ears.port":`Des oreilles proches de la tête, dégagées par votre coiffure : pensez à les protéger du soleil.`,"neck.longueur":`Un cou long et fin, mis en valeur par une coiffure attachée bas ; il s’entretient comme le visage.`,"hair.coiffage":`Le plaqué vous va : il dégage l’ovale. Des mèches libres devant les oreilles le rendent plus doux.`,"hair.tension":`Votre coiffure vous va ; il faut seulement la faire sans serrer pour préserver la lisière.`,"hair.nature":`Des cheveux lisses et souples, qui demandent peu : un lavage doux et des longueurs démêlées.`,"hair.couleur":`Le brun foncé crée votre contraste ; les bruns profonds vous vont mieux que les teintes claires.`};for(let[e,t]of Object.entries(d))for(let n of t.obs)n.vaBien??=g[`${e}.${n.id}`];var _={coiffeur:`Coiffure`,cheveux:`Coiffure`,maquillage:`Beauté`,liner:`Beauté`,blush:`Beauté`,opticien:`Chez le pro`,"routine-peau":`Soin`,solaire:`Soin`,"gua-sha":`Soin`,massage:`Soin`,drainage:`Soin`,levres:`Soin`},v=[`Soin`,`Beauté`,`Coiffure`,`Hygiène de vie`,`Chez le pro`];for(let[,e]of Object.entries(d))for(let t of e.obs)for(let e of t.conseils??[])e.famille||=e.produit===`rouge-levres`?`Beauté`:e.fiche&&_[e.fiche]||`Soin`,e.pour||=e.famille===`Coiffure`?[`coupe`,`valeur`]:e.famille===`Beauté`?[`valeur`]:e.fiche===`opticien`?[`lunettes`]:[`peau`];var y={atouts:[{titre:`Un ovale équilibré`,texte:`Pommettes au point le plus large, front et mâchoire plus étroits : la plupart des coupes et des montures vous vont.`,zone:`cheeks`},{titre:`Un regard structuré`,texte:`Yeux en amande bien espacés, sourcils fournis et foncés : un contraste naturel.`,zone:`eyes`},{titre:`Des taches de rousseur`,texte:`Une signature à garder visible, avec un teint léger.`,zone:`nose`}],attention:[{titre:`Une peau claire exposée`,texte:`Front, nez, joues et oreilles découverts : la protection solaire est la priorité.`,zone:`cheeks`},{titre:`Une coiffure tirée chaque jour`,texte:`À faire sans serrer pour préserver la lisière.`,zone:`hair`}]},b=[{id:`objectif`,titre:`Qu’est-ce qui compte le plus pour vous ?`,choix:[[`valeur`,`Mettre mon visage en valeur`],[`peau`,`Prendre soin de ma peau`],[`coupe`,`Changer de coupe`],[`lunettes`,`Trouver mes lunettes`],[`tout`,`Un peu de tout`]]},{id:`peau`,titre:`Comment sentez-vous votre peau en fin de journée ?`,choix:[[`seche`,`Elle tiraille`],[`grasse`,`Elle brille partout`],[`mixte`,`Elle brille au centre seulement`],[`normale`,`Confortable`],[`inconnue`,`Je ne sais pas`]]},{id:`temps`,titre:`Combien de temps par jour pour vous ?`,choix:[[`court`,`5 minutes`],[`moyen`,`10 minutes`],[`long`,`Plus de 10 minutes`]]},{id:`budget`,titre:`Votre budget pour les produits ?`,choix:[[`serre`,`L’essentiel seulement`],[`moyen`,`Raisonnable`],[`libre`,`Pas de limite particulière`]]},{id:`deja`,titre:`Qu’utilisez-vous déjà ?`,multiple:!0,choix:[[`nettoyant`,`Un nettoyant doux`],[`ceramides`,`Une crème hydratante`],[`spf50`,`Une protection solaire`],[`baume-spf`,`Un baume à lèvres`],[`bb-creme`,`Un teint léger`]]}],x=[`nettoyant`,`ceramides`,`spf50`,`baume-spf`],S={seche:`Votre peau tiraille : choisissez une version plus riche de la crème (crème plutôt que gel), surtout le soir.`,grasse:`Votre peau brille : gardez une texture gel légère, non comédogène, et ne lavez pas plus de deux fois par jour.`,mixte:`Votre peau brille au centre : gel léger sur le front, le nez et le menton, crème sur les joues.`,normale:`Votre peau est confortable : la texture gel-crème convient matin et soir.`,inconnue:`Observez votre peau en fin de journée : si elle tiraille, une crème plus riche ; si elle brille, un gel.`},C=e=>{let t=e.charAt(0).toLowerCase()+e.slice(1),n=t.split(` `)[0];return(/[sx]$/.test(n)?`Vos `:`Votre `)+t},w=e=>[...new Set([...e.produit?[e.produit]:[],...e.produits??[]])],T=new Map;function E(){T.clear();for(let[e,t]of Object.entries(d))for(let n of t.obs)for(let t of n.sens===`obs`?n.conseils??[]:[])for(let r of w(t)){let i=T.get(r)??[];i.push({zone:e,obs:n.label,objectif:t.objectif,raison:t.lien}),T.set(r,i)}}E();function D(e){let t=e=>{for(let t of Object.keys(e))delete e[t]};t(d),Object.assign(d,e.zones),t(y),Object.assign(y,e.bilan),t(o),Object.assign(o,e.ensemble),p.splice(0,p.length,...e.fiches),f.splice(0,f.length,...e.routine),E()}var O=e=>T.get(e)??[],k=e=>[...new Set(f.filter(t=>e.produit&&t.produit===e.produit||e.geste&&t.geste===e.geste).map(e=>e.quand))];export{w as _,p as a,b as c,h as d,S as f,k as g,D as h,v as i,f as l,m,o as n,a as o,d as p,x as r,s,y as t,l as u,O as v,C as y};